askql_sql:
SELECT COUNT(*) 
FROM lineitem 
WHERE l_discount = 0;

SELECT l_extendedprice * (1 - l_discount) AS discounted_price
FROM lineitem
WHERE l_linenumber = 1;

SELECT o_totalprice 
FROM orders 
WHERE o_orderkey = 32;

SELECT o_orderkey 
FROM orders 
WHERE o_totalprice BETWEEN 200000 AND 300000;

SELECT COUNT(*) 
FROM orders 
WHERE o_orderdate >= '1998-01-01' AND o_orderdate < '1999-01-01' AND o_totalprice < 950;

SELECT COUNT(*) 
FROM lineitem 
WHERE l_shipdate = '1993-12-04';

SELECT COUNT(*) 
FROM customer 
WHERE c_mktsegment = 'AUTOMOBILE';

SELECT COUNT(*) 
FROM lineitem 
WHERE l_quantity > 10 AND l_returnflag = 'R';

SELECT c_custkey 
FROM customer 
WHERE c_acctbal < 0;

SELECT COUNT(*) 
FROM lineitem 
WHERE l_shipinstruct = 'DELIVER IN PERSON';

SELECT COUNT(*) 
FROM supplier 
WHERE s_acctbal < 0;

SELECT COUNT(*) 
FROM nation 
WHERE n_regionkey = 2;

SELECT COUNT(*) 
FROM part 
WHERE p_retailprice > 1900;

SELECT COUNT(*) 
FROM lineitem 
WHERE l_shipmode = 'rail' AND l_quantity < 30;

SELECT COUNT(*) 
FROM partsupp 
WHERE ps_availqty < 10;

SELECT COUNT(DISTINCT l_partkey) 
FROM lineitem 
WHERE l_orderkey = 5 AND l_returnflag = 'R';

SELECT COUNT(*) 
FROM part 
WHERE p_type = 'promo brushed steel' AND p_mfgr = 'Manufacturer#5';

SELECT c_name, c_phone 
FROM customer 
WHERE c_acctbal > 9000;

SELECT o_orderdate 
FROM orders 
WHERE o_orderpriority = 'Urgent';

SELECT DISTINCT p_brand 
FROM part 
WHERE p_type = 'promo brushed steel';

SELECT COUNT(*) 
FROM part 
WHERE p_container = 'JUMBO CASE';

SELECT COUNT(*) 
FROM customer 
WHERE c_mktsegment = 'MACHINERY' AND c_acctbal < 0;

SELECT p_partkey 
FROM part 
WHERE p_retailprice > (SELECT AVG(p_retailprice) FROM part);

SELECT o_orderdate 
FROM orders 
WHERE o_totalprice = (SELECT MAX(o_totalprice) FROM orders);

SELECT SUM(o_totalprice) AS total_price
FROM orders
WHERE o_custkey = 13;

SELECT c_name 
FROM customer 
WHERE c_acctbal < 0;

SELECT COUNT(*) 
FROM partsupp 
WHERE ps_availqty < 100;

SELECT COUNT(*) 
FROM customer 
WHERE c_mktsegment = 'FURNITURE';

SELECT p_comment 
FROM part 
WHERE p_name = 'burlywood plum powder puff mint';

SELECT c_name 
FROM customer 
WHERE c_acctbal = (SELECT MIN(c_acctbal) FROM customer);

SELECT MAX(l_shipdate) AS latest_ship_date
FROM lineitem
WHERE l_orderkey = 1;

SELECT p_name 
FROM part 
WHERE p_type = 'promo brushed steel';

SELECT o_totalprice, o_orderpriority 
FROM orders 
WHERE o_orderkey = 33;

SELECT p_retailprice 
FROM part 
WHERE p_type = 'LARGE BURNISHED COPPER';

SELECT c_mktsegment, c_name, c_address, c_phone 
FROM customer 
WHERE c_custkey = 3;

SELECT n_name 
FROM nation 
WHERE n_nationkey = (SELECT s_nationkey FROM supplier WHERE s_suppkey = 34);

SELECT COUNT(*) 
FROM customer 
WHERE c_acctbal < 0;

SELECT n_name 
FROM nation 
WHERE n_nationkey = (SELECT s_nationkey FROM supplier WHERE s_suppkey = 1);

SELECT COUNT(*) 
FROM orders 
WHERE o_orderpriority = '1-URGENT' AND o_shippriority < 5;

SELECT COUNT(*) 
FROM orders 
WHERE strftime('%Y', o_orderdate) = '1994';

SELECT MIN(p_size) 
FROM part 
WHERE p_container = 'JUMBO CASE';

SELECT COUNT(*) 
FROM customer 
WHERE c_mktsegment = 'FURNITURE' AND c_nationkey = 1;

SELECT COUNT(*) 
FROM orders 
WHERE strftime('%Y', o_orderdate) = '1998';

SELECT DISTINCT l_shipmode 
FROM lineitem 
WHERE l_shipdate = '1994-12-31';

SELECT p_name 
FROM part 
WHERE p_partkey NOT IN (SELECT l_partkey FROM lineitem WHERE l_discount > 0);

SELECT COUNT(*) 
FROM lineitem 
WHERE l_quantity > 40 AND l_shipmode = 'Air';

SELECT COUNT(*) 
FROM orders 
WHERE o_orderpriority = 'MEDIUM' AND o_shippriority = 1;
